import{_ as d,c as a,o as r,ae as e}from"./chunks/framework.BbFa6TS3.js";const c=JSON.parse('{"title":"AI 知识库","description":"","frontmatter":{},"headers":[],"relativePath":"fe/ai/konwledge.md","filePath":"fe/ai/konwledge.md"}'),l={name:"fe/ai/konwledge.md"};function i(n,t,o,s,h,g){return r(),a("div",null,t[0]||(t[0]=[e(`<h1 id="ai-知识库" tabindex="-1">AI 知识库 <a class="header-anchor" href="#ai-知识库" aria-label="Permalink to &quot;AI 知识库&quot;">​</a></h1><h2 id="基础知识" tabindex="-1">基础知识 <a class="header-anchor" href="#基础知识" aria-label="Permalink to &quot;基础知识&quot;">​</a></h2><ol><li><p>定义 在人工智能领域，知识库是指用于存储、组织和检索结构化或半结构化知识的信息系统。这些知识可以是事实、规则、概念、关系、文档内容、FAQ 问答等，通常被 AI 系统用于推理、问答、决策支持等任务。</p></li><li><p>本质 知识库是 AI 系统的“知识大脑”，它与模型（如 LLM）不同：</p></li></ol><p>知识库 = 存储信息</p><p>模型 = 理解与生成信息</p><h2 id="技术构成" tabindex="-1">技术构成 <a class="header-anchor" href="#技术构成" aria-label="Permalink to &quot;技术构成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>说明</th></tr></thead><tbody><tr><td><strong>数据源</strong></td><td>原始信息来源，如文档、网页、数据库、API、问答对等</td></tr><tr><td><strong>数据预处理</strong></td><td>对原始数据进行清洗、分词、摘要、格式化等处理</td></tr><tr><td><strong>索引系统</strong></td><td>将知识转化为向量或倒排索引，方便快速检索</td></tr><tr><td><strong>嵌入模型</strong></td><td>用于将文本转成向量表示（如 <code>text-embedding-ada-002</code>）</td></tr><tr><td><strong>检索引擎</strong></td><td>向量搜索（如 FAISS、Milvus）或关键词搜索（如 Elasticsearch）</td></tr><tr><td><strong>问答接口</strong></td><td>用户提出问题，系统从知识库中提取相关知识进行回答</td></tr><tr><td><strong>反馈与更新</strong></td><td>用户交互反馈可反向更新知识库内容和质量</td></tr></tbody></table><h2 id="知识类型划分" tabindex="-1">知识类型划分 <a class="header-anchor" href="#知识类型划分" aria-label="Permalink to &quot;知识类型划分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>举例</th><th>结构化程度</th></tr></thead><tbody><tr><td><strong>结构化知识</strong></td><td>数据库中的产品信息、用户资料</td><td>高</td></tr><tr><td><strong>半结构化知识</strong></td><td>Markdown 文档、网页 HTML、FAQ 文档</td><td>中</td></tr><tr><td><strong>非结构化知识</strong></td><td>自然语言文本、书籍、报告、邮件</td><td>低</td></tr></tbody></table><h2 id="知识库与大语言模型-llm-的结合-rag-技术" tabindex="-1">知识库与大语言模型（LLM）的结合：RAG 技术 <a class="header-anchor" href="#知识库与大语言模型-llm-的结合-rag-技术" aria-label="Permalink to &quot;知识库与大语言模型（LLM）的结合：RAG 技术&quot;">​</a></h2><p>什么是 RAG（Retrieval-Augmented Generation）？</p><p>RAG 是一种增强生成式 AI 的方法，它将知识库作为外部知识源，引导语言模型进行更准确的生成。</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[用户问题] → [向量化] → [在知识库中检索 Top-K 文本]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                             ↓</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">           [问题 + Top-K 文本] → [送入LLM进行生成回答]</span></span></code></pre></div><p>好处：</p><ol><li>降低幻觉（hallucination）率</li><li>提高事实准确性</li><li>实时更新知识而无需重新训练模型</li><li>支持私有领域知识注入（如公司内部手册）</li></ol><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>行业</th><th>应用场景</th><th>实例说明</th></tr></thead><tbody><tr><td><strong>客服与问答</strong></td><td>智能客服机器人</td><td>接入企业产品 FAQ 知识库，24 小时回答客户问题</td></tr><tr><td><strong>企业内部搜索</strong></td><td>企业知识助手</td><td>员工搜索内部文档、制度、流程、技术资料</td></tr><tr><td><strong>医疗行业</strong></td><td>临床问答系统</td><td>基于医学文献、指南、病例的自动问答系统</td></tr><tr><td><strong>法律行业</strong></td><td>法律法规查询</td><td>查询法条、判例、律师文书模板等内容</td></tr><tr><td><strong>教育行业</strong></td><td>智能学习问答</td><td>学生提问教材相关内容，AI 回答</td></tr><tr><td><strong>金融行业</strong></td><td>风控知识问答</td><td>提供金融产品、风控模型、政策文件的知识检索</td></tr><tr><td><strong>开发者平台</strong></td><td>技术文档助手</td><td>检索 API 文档、SDK 使用说明并结合代码示例回答</td></tr><tr><td><strong>电商平台</strong></td><td>商品知识问答</td><td>商品特性、售后政策、使用指南的语义检索问答</td></tr></tbody></table><h2 id="典型技术栈" tabindex="-1">典型技术栈 <a class="header-anchor" href="#典型技术栈" aria-label="Permalink to &quot;典型技术栈&quot;">​</a></h2><ol><li><p>嵌入模型（Embedding Model）</p><ul><li>OpenAI：text-embedding-3-small、text-embedding-ada-002</li><li>HuggingFace：sentence-transformers 系列</li><li>自建模型：BGE、Cohere、ERNIE-BERT 等</li></ul></li><li><p>检索系统</p><ul><li>向量数据库：FAISS（Facebook）、Milvus（Zilliz）、Weaviate、Pinecone</li><li>搜索引擎：Elasticsearch（支持关键词 + 向量）</li></ul></li><li><p>应用框架</p><ul><li>LangChain / LlamaIndex：构建 RAG 工作流</li><li>Haystack：端到端的问答系统构建框架</li><li>ChatGPT Plugins / RAG 应用：快速对接现有 LLM</li></ul></li></ol><h2 id="构建一个知识库系统的步骤" tabindex="-1">构建一个知识库系统的步骤 <a class="header-anchor" href="#构建一个知识库系统的步骤" aria-label="Permalink to &quot;构建一个知识库系统的步骤&quot;">​</a></h2><ol><li>收集数据：从网站、文档、PDF 等提取内容</li><li>数据清洗与拆分：分段（chunking）+ 清洗无用内容</li><li>文本向量化：使用嵌入模型转成向量</li><li>存储向量：保存至向量数据库</li><li>建立检索接口：构建语义检索功能</li><li>LLM 问答对接：检索结果 + Prompt 合成 → 喂给语言模型生成最终回答</li><li>上线使用 + 用户反馈 + 动态更新</li></ol><h2 id="发展趋势" tabindex="-1">发展趋势 <a class="header-anchor" href="#发展趋势" aria-label="Permalink to &quot;发展趋势&quot;">​</a></h2><table tabindex="0"><thead><tr><th>趋势方向</th><th>说明</th></tr></thead><tbody><tr><td>多模态知识库</td><td>同时支持文本、图片、音频、视频等形式</td></tr><tr><td>实时更新能力</td><td>自动监听数据源变化并更新嵌入</td></tr><tr><td>私有部署</td><td>保障企业数据隐私与合规性</td></tr><tr><td>个性化知识库</td><td>每个用户都有个性化知识视图</td></tr><tr><td>与 Agent 结合</td><td>知识库作为智能体（Agent）的长期记忆</td></tr></tbody></table>`,23)]))}const b=d(l,[["render",i]]);export{c as __pageData,b as default};
